insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('566', '괄도네넴띤', 'Gwal-Do-Ne-Nem-Ttin', 'outdated-slang', 'yaminjeongeum', '''팔도비빔면''을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Eine Umschreibung der Nudelmarke Paldo Bibimmyeon mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of the noodle brand Paldo Bibimmyeon", "es": "Reescritura del fideo Paldo Bibimmyeon con hangul de forma parecida", "ja": "「八道ビビン麺」を字の形が似たハングルに置き換えた表記", "vi": "Cách viết lại tên mì Paldo Bibimmyeon bằng chữ Hàn trông giống"}'::jsonb, '[괄도네넴띤]', '[{"type": "명사", "examples": [{"de": "Im Kiosk soll es Gwaldo-nenemttin geben — soll ich eins mitbringen?", "es": "Dicen que llegó Gwaldo-nenemttin a la tienda, ¿traigo uno?", "ja": "コンビニにクァルドネネムティン入ったって、買ってこようか?", "vi": "Nghe nói cửa hàng tiện lợi có Gwaldo-nenemttin rồi, mua không?", "eng": "They say the convenience store got Gwaldo-nenemttin in — should I grab one?", "kor": "편의점에 괄도네넴띤 들어왔대, 사올까?"}], "definition": "라면 ''팔도비빔면''의 글자를 모양이 닮은 한글로 바꿔 쓴 야민정음 표기. ''팔''을 ''괄''로, ''비빔면''을 ''네넴띤''으로 바꾼 것으로, 멀리서 보면 원래 글자처럼 보인다. 어느 쪽으로 검색해도 가리키는 제품은 같다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung der Instantnudel Paldo Bibimmyeon, bei der jede Silbe durch eine ähnlich aussehende ersetzt wird: 팔→괄, 비빔면→네넴띤. Aus der Ferne liest es sich wie das Original. Beide Schreibungen meinen dasselbe Produkt.", "en": "A yaminjeongeum respelling of the instant noodle Paldo Bibimmyeon, swapping each syllable for a look-alike: 팔→괄, 비빔면→네넴띤. Squint and it reads as the original. Either spelling points to the same product.", "es": "Reescritura en yaminjeongeum del fideo instantáneo Paldo Bibimmyeon, cambiando cada sílaba por otra de forma similar: 팔→괄, 비빔면→네넴띤. De lejos se lee como el original. Ambas grafías designan el mismo producto.", "ja": "即席麺「팔도비빔면(八道ビビン麺)」の文字を形の似たハングルに置き換えたヤミン正音表記。팔→괄、비빔면→네넴띤と替えており、遠目には元の文字に見える。どちらの表記も同じ商品を指す。", "vi": "Cách viết yaminjeongeum của mì ăn liền Paldo Bibimmyeon, thay từng âm tiết bằng chữ trông giống: 팔→괄, 비빔면→네넴띤. Nhìn xa vẫn ra chữ gốc. Cả hai cách viết đều chỉ cùng một sản phẩm."}}]'::jsonb, '야민정음(글자 모양이 닮은 한글로 바꿔 쓰는 인터넷 표기법)은 디시인사이드 야구 갤러리에서 2014년경부터 퍼졌다는 설이 널리 알려져 있으나 확정된 기원은 아니다. ''괄도네넴띤''은 온라인에서 쓰이던 이 표기를 2019년 2월 팔도가 비빔면 출시 35주년 한정판 제품명으로 공식 채택하면서 대중에 알려졌고, 한정판 500만 개가 한 달 만에 완판됐다.', '{"de": "Yaminjeongeum — Hangul mit ähnlich aussehenden Zeichen umschreiben — soll sich laut verbreiteter Darstellung ab etwa 2014 vom Baseball-Board auf DCInside ausgebreitet haben; gesichert ist das nicht. Diese Schreibung kursierte online, bis Paldo sie im Februar 2019 als offiziellen Namen einer Sonderedition zum 35. Jubiläum übernahm; die fünf Millionen Stück waren in einem Monat ausverkauft.", "en": "Yaminjeongeum — rewriting Hangul with look-alike letters — is widely said to have spread from DCInside''s baseball board around 2014, though that origin is not settled. This particular spelling circulated online until February 2019, when Paldo adopted it as the official name of a 35th-anniversary limited edition; the five million units sold out in a month.", "es": "El yaminjeongeum —reescribir hangul con letras parecidas— se atribuye normalmente al tablón de béisbol de DCInside hacia 2014, aunque ese origen no está confirmado. Esta grafía circulaba en internet hasta que en febrero de 2019 Paldo la adoptó como nombre oficial de una edición limitada por el 35.º aniversario; los cinco millones de unidades se agotaron en un mes.", "ja": "ヤミン正音(形の似たハングルに置き換える書き方)はDCインサイドの野球ギャラリーで2014年頃から広まったという説が知られるが、確定した起源ではない。この表記は online で使われていたものを2019年2月に八道がビビン麺発売35周年記念の限定版の正式名称として採用し、限定500万個が1か月で完売した。", "vi": "Yaminjeongeum — viết lại chữ Hàn bằng những chữ trông giống — thường được cho là lan ra từ diễn đàn bóng chày của DCInside khoảng năm 2014, nhưng nguồn gốc này chưa chắc chắn. Cách viết này lưu hành trên mạng cho tới tháng 2/2019, khi Paldo lấy nó làm tên chính thức cho bản giới hạn kỷ niệm 35 năm; năm triệu gói bán hết trong một tháng."}'::jsonb, '정식 표기가 아니라 장난스러운 야민정음 표기다. 검색이나 주문은 ''팔도비빔면''으로 해야 하고, 어느 쪽으로 불러도 같은 제품을 가리킨다. 2019년 유행이 지난 뒤로는 그 시절 밈을 아는 사람끼리 쓰는 말이 됐다.', '{"de": "Keine offizielle, sondern eine spielerische Yaminjeongeum-Schreibung: Suchen oder bestellen muss man unter 팔도비빔면, auch wenn beide Namen dasselbe Produkt meinen. Nach dem Hype von 2019 lebt es vor allem als Insiderwitz weiter.", "en": "Not a real spelling but a playful yaminjeongeum one — search or order under 팔도비빔면, though either name means the same product. Since the 2019 craze passed it survives mostly as an in-joke.", "es": "No es una grafía oficial sino un juego de yaminjeongeum: busca o pide como 팔도비빔면, aunque ambos nombres designan el mismo producto. Pasada la fiebre de 2019, sobrevive como chiste interno.", "ja": "正式表記ではなく遊びのヤミン正音表記。検索や注文は「팔도비빔면」で行う必要があるが、どちらで呼んでも同じ商品を指す。2019年のブームが去ってからは当時のミームを知る人同士の言葉になった。", "vi": "Không phải cách viết chính thức mà là lối viết yaminjeongeum đùa vui: tìm hay đặt hàng phải dùng 팔도비빔면, dù cả hai tên đều chỉ một sản phẩm. Sau cơn sốt 2019, nó chỉ còn là câu đùa của người biết meme thời đó."}'::jsonb, array['머박', '댕댕이', '띵곡', '커엽다']::text[], NULL, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Paldo Bibimmyeon, spelled in look-alike Hangul"}, {"lang": "🇯🇵 JA", "text": "八道ビビン麺のヤミン正音表記"}, {"lang": "🇨🇳 ZH", "text": "八道拌面的\"野民正音\"写法"}, {"lang": "🇻🇳 VI", "text": "Paldo Bibimmyeon viết kiểu chữ giống"}, {"lang": "🇪🇸 ES", "text": "Paldo Bibimmyeon escrito con hangul parecido"}, {"lang": "🇩🇪 DE", "text": "Paldo Bibimmyeon in Ähnlichkeits-Hangul"}]'::jsonb),
('567', '띵문', 'Tting-mun', 'outdated-slang', 'yaminjeongeum', '‘명문’을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 명문 (renommiert / meisterhaft) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 명문 (prestigious / masterful)", "es": "Reescritura de 명문 (prestigioso / magistral) con hangul parecido", "ja": "「명문(名門・名文)」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 명문 (danh giá / văn hay) bằng chữ Hàn trông giống"}'::jsonb, '[띵문]', '[{"type": "명사", "examples": [{"de": "Angeblich hat es an einer Tting-mun-Uni geklappt.", "es": "Dicen que entró en una uni tting-mun.", "ja": "あの子、띵문대に受かったって。", "vi": "Nghe nói nó đỗ trường tting-mun rồi.", "eng": "I heard they got into a tteeng-mun (top) university.", "kor": "걔 띵문대 붙었대."}, {"de": "Dieser Kommentar ist reinster Tting-mun.", "es": "Este comentario es tting-mun total.", "ja": "このコメント、完全に띵문だわ。", "vi": "Bình luận này đúng là tting-mun.", "eng": "This comment is pure tting-mun writing.", "kor": "이 댓글 완전 띵문이다."}], "definition": "‘명문’의 ‘명’을 모양이 닮은 ‘띵’으로 바꿔 쓴 야민정음 표기. 이름난 학교·집안(名門, ‘띵문대’)이나 잘 쓴 글(名文)을 장난스럽게 가리킨다. ‘띵곡’·‘띵작’과 같은 계열이다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 명문, bei der 명 durch das ähnliche 띵 ersetzt wird. Meint scherzhaft eine renommierte Schule oder Familie (名門, etwa 띵문대) oder einen meisterhaft geschriebenen Text (名文). Gehört zur Familie von 띵곡 und 띵작.", "en": "A yaminjeongeum spelling of 명문, swapping 명 for the look-alike 띵. It playfully means either a prestigious school or family (名門, as in 띵문대 for a top university) or a brilliantly written piece (名文). Same family as 띵곡 and 띵작.", "es": "Grafía yaminjeongeum de 명문, cambiando 명 por el parecido 띵. Designa en broma una escuela o familia prestigiosa (名門, como 띵문대) o un texto magistral (名文). De la misma familia que 띵곡 y 띵작.", "ja": "「명문」の「명」を形の似た「띵」に替えたヤミン正音表記。名門校・名家(「띵문대」)や名文をおどけて指す。「띵곡」「띵작」と同じ系列。", "vi": "Cách viết yaminjeongeum của 명문, đổi 명 thành 띵 trông giống. Chỉ vui một trường hay gia đình danh giá (名門, như 띵문대) hoặc một bài viết hay (名文). Cùng họ với 띵곡 và 띵작."}}]'::jsonb, '글자 모양이 닮은 한글로 바꿔 쓰는 인터넷 표기 놀이 ‘야민정음’의 한 예다. ‘명’을 ‘띵’으로 바꾸는 방식은 명곡→띵곡, 명작→띵작, 명언→띵언처럼 여러 단어에 두루 쓰였다.', '{"de": "Ein Beispiel für Yaminjeongeum, das Internetspiel, Hangul mit ähnlich aussehenden Buchstaben umzuschreiben. Der Tausch 명→띵 wurde auf viele Wörter angewandt: 명곡→띵곡, 명작→띵작, 명언→띵언.", "en": "One example of yaminjeongeum, the internet game of respelling Hangul with look-alike letters. The 명→띵 swap was applied across many words: 명곡→띵곡, 명작→띵작, 명언→띵언.", "es": "Un ejemplo del yaminjeongeum, el juego de internet de reescribir hangul con letras parecidas. El cambio 명→띵 se aplicó a muchas palabras: 명곡→띵곡, 명작→띵작, 명언→띵언.", "ja": "似た形のハングルに置き換えるネット上の表記遊び「ヤミン正音」の一例。「명→띵」の置き換えは명곡→띵곡、명작→띵작、명언→띵언のように広く使われた。", "vi": "Một ví dụ của yaminjeongeum, trò viết lại Hangul bằng chữ trông giống trên mạng. Kiểu đổi 명→띵 được áp dụng cho nhiều từ: 명곡→띵곡, 명작→띵작, 명언→띵언."}'::jsonb, '주로 ‘띵문대’ 꼴로 좋은 대학을 장난스럽게 부를 때 쓴다. 글로만 통하는 말이라 소리 내어 말하면 잘 못 알아듣는다.', '{"de": "Meist als 띵문대, scherzhaft für eine Spitzenuni. Funktioniert nur schriftlich; laut gesagt versteht man es kaum.", "en": "Mostly seen as 띵문대, a joking name for a top university. It only works in writing; said aloud it tends not to land.", "es": "Sobre todo como 띵문대, forma de broma para una gran universidad. Solo funciona por escrito; dicho en voz alta no se entiende bien.", "ja": "主に「띵문대」の形で、良い大学をおどけて呼ぶときに使う。文字でしか通じず、口に出すと伝わりにくい。", "vi": "Chủ yếu dùng dạng 띵문대 để gọi đùa trường đại học tốt. Chỉ hiểu khi viết; nói ra thì khó ai hiểu."}'::jsonb, array['띵곡', '띵작', '댕댕이']::text[], array['띵문대']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Prestigious / masterful (look-alike spelling of 명문)"}, {"lang": "🇯🇵 JA", "text": "名門・名文(명문のヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "名门/名文(명문的形近写法)"}, {"lang": "🇻🇳 VI", "text": "Danh giá / văn hay (cách viết giống của 명문)"}, {"lang": "🇪🇸 ES", "text": "Prestigioso / magistral (grafía parecida de 명문)"}, {"lang": "🇩🇪 DE", "text": "Renommiert / meisterhaft (Ähnlichkeitsschreibung von 명문)"}]'::jsonb),
('568', '세종머앟', 'Se-jong-meo-ak', 'outdated-slang', 'yaminjeongeum', '‘세종대왕’을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 세종대왕 (König Sejong) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 세종대왕 (King Sejong the Great)", "es": "Reescritura de 세종대왕 (el rey Sejong) con hangul parecido", "ja": "「世宗大王」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 세종대왕 (vua Sejong) bằng chữ Hàn trông giống"}'::jsonb, '[세종머악]', '[{"type": "명사", "examples": [{"de": "Wenn Se-jong-meo-ak das sähe, würde er weinen.", "es": "Si ve esto, se-jong-meo-ak se echa a llorar.", "ja": "これ見たら세종머앟が泣いて帰るよ。", "vi": "Thấy cái này chắc se-jong-meo-ak khóc mất.", "eng": "King Sejong (se-jong-meo-ak) would weep if he saw this.", "kor": "이거 보면 세종머앟이 울고 가신다."}], "definition": "한글을 만든 ‘세종대왕’의 ‘대’를 ‘머’로, ‘왕’을 ‘앟’으로 바꿔 쓴 야민정음 표기. 한글을 비틀어 노는 놀이에 한글 창제자 이름을 붙였다는 아이러니 때문에 야민정음의 상징처럼 쓰였다. ‘세종머왕’으로도 쓴다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 세종대왕, dem König, der Hangul schuf: 대 wird zu 머, 왕 zu 앟. Die Ironie, Hangul ausgerechnet am Namen seines Erfinders zu verbiegen, machte es zu einer Art Maskottchen des Yaminjeongeum. Auch 세종머왕 geschrieben.", "en": "A yaminjeongeum spelling of 세종대왕, the king who created Hangul, with 대 turned into 머 and 왕 into 앟. The irony of twisting Hangul on the name of its own inventor made it a kind of mascot for yaminjeongeum. Also written 세종머왕.", "es": "Grafía yaminjeongeum de 세종대왕, el rey que creó el hangul, con 대 convertido en 머 y 왕 en 앟. La ironía de deformar el hangul en el nombre de su propio creador la volvió casi la mascota del yaminjeongeum. También se escribe 세종머왕.", "ja": "ハングルを作った「世宗大王」の「대」を「머」、「왕」を「앟」に替えたヤミン正音表記。ハングルを崩す遊びに創製者の名を使う皮肉から、ヤミン正音の象徴のように使われた。「세종머왕」とも書く。", "vi": "Cách viết yaminjeongeum của 세종대왕, vị vua tạo ra Hangul, đổi 대 thành 머 và 왕 thành 앟. Sự trớ trêu khi bóp méo Hangul ngay trên tên người sáng tạo ra nó khiến từ này thành biểu tượng của yaminjeongeum. Cũng viết 세종머왕."}}]'::jsonb, '야민정음은 디시인사이드 야구 갤러리에서 퍼졌다는 설이 알려진 표기 놀이로, 이름도 ‘야갤’과 ‘훈민정음’을 합친 것이다. ‘대→머’(ㄷ과 ㅁ, ㅐ와 ㅓ의 모양이 닮음)와 ‘왕→앟’ 두 가지 바꾸기가 함께 들어간 예다.', '{"de": "Yaminjeongeum ist ein Schreibspiel, das sich angeblich von der Baseball-Galerie von DC Inside aus verbreitete; der Name verbindet 야갤 mit 훈민정음. Dieses Wort kombiniert zwei Tausche: 대→머 (ㄷ/ㅁ und ㅐ/ㅓ ähneln sich) und 왕→앟.", "en": "Yaminjeongeum is a spelling game said to have spread from DC Inside baseball gallery; its name blends 야갤 (the gallery) with 훈민정음 (the original name of Hangul). This word combines two swaps: 대→머 (ㄷ/ㅁ and ㅐ/ㅓ look alike) and 왕→앟.", "es": "El yaminjeongeum es un juego ortográfico que, según se dice, se extendió desde la galería de béisbol de DC Inside; su nombre une 야갤 y 훈민정음. Esta palabra combina dos cambios: 대→머 (ㄷ/ㅁ y ㅐ/ㅓ se parecen) y 왕→앟.", "ja": "ヤミン正音はDCインサイド野球ギャラリーから広まったとされる表記遊びで、名前も「야갤」と「訓民正音」を合わせたもの。「대→머」(ㄷとㅁ、ㅐとㅓが似る)と「왕→앟」の二つの置き換えが入った例。", "vi": "Yaminjeongeum là trò chơi chữ được cho là lan ra từ gallery bóng chày DC Inside; tên gọi ghép 야갤 với 훈민정음. Từ này kết hợp hai kiểu đổi: 대→머 (ㄷ/ㅁ và ㅐ/ㅓ trông giống) và 왕→앟."}'::jsonb, '한글날이나 맞춤법 이야기가 나올 때 농담으로 쓰는 경우가 많다. 실제 역사 인물을 가리키는 말이라 진지한 글에는 쓰지 않는다.', '{"de": "Oft als Scherz am Hangul-Tag oder in Rechtschreibdebatten. Da es eine reale historische Person benennt, gehört es nicht in ernste Texte.", "en": "Often used as a joke around Hangul Day or in spelling debates. Since it names a real historical figure, keep it out of serious writing.", "es": "Se usa mucho en broma el Día del Hangul o en debates ortográficos. Como nombra a una figura histórica real, no va en textos serios.", "ja": "ハングルの日や綴りの話題で冗談として使うことが多い。実在の歴史人物を指すので、真面目な文章には使わない。", "vi": "Hay dùng đùa vào Ngày Hangul hoặc khi bàn chuyện chính tả. Vì chỉ nhân vật lịch sử có thật, không dùng trong văn bản nghiêm túc."}'::jsonb, array['머통령', '머한민국', '댕댕이']::text[], array['세종머왕']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "King Sejong (look-alike spelling)"}, {"lang": "🇯🇵 JA", "text": "世宗大王(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "世宗大王(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Vua Sejong (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "El rey Sejong (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "König Sejong (Ähnlichkeitsschreibung)"}]'::jsonb),
('569', '머통령', 'Meo-tong-ryeong', 'outdated-slang', 'yaminjeongeum', '‘대통령’을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 대통령 (Präsident) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 대통령 (president)", "es": "Reescritura de 대통령 (presidente) con hangul parecido", "ja": "「대통령(大統領)」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 대통령 (tổng thống) bằng chữ Hàn trông giống"}'::jsonb, '[머통녕]', '[{"type": "명사", "examples": [{"de": "Die Meo-tong-ryeong-Wahl ist schon nächsten Monat?", "es": "¿Las elecciones a meo-tong-ryeong ya son el mes que viene?", "ja": "머통령選挙、もう来月なの?", "vi": "Bầu cử meo-tong-ryeong đã là tháng sau rồi à?", "eng": "The meo-tong-ryeong election is already next month?", "kor": "머통령 선거가 벌써 다음 달이야?"}], "definition": "‘대통령’의 ‘대’를 모양이 닮은 ‘머’로 바꿔 쓴 야민정음 표기. 뜻은 대통령과 같고, 인터넷 게시판에서 장난스럽게 부를 때 쓴다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 대통령, bei der 대 durch das ähnliche 머 ersetzt wird. Bedeutet dasselbe wie Präsident und wird in Foren scherzhaft benutzt.", "en": "A yaminjeongeum spelling of 대통령 with 대 swapped for the look-alike 머. It means the same as president, used playfully on internet boards.", "es": "Grafía yaminjeongeum de 대통령, cambiando 대 por el parecido 머. Significa lo mismo que presidente y se usa en broma en foros.", "ja": "「대통령」の「대」を形の似た「머」に替えたヤミン正音表記。意味は大統領と同じで、ネット掲示板でおどけて呼ぶときに使う。", "vi": "Cách viết yaminjeongeum của 대통령, đổi 대 thành 머 trông giống. Nghĩa như tổng thống, dùng đùa trên diễn đàn mạng."}}]'::jsonb, '야민정음의 ‘대→머’ 바꾸기(ㄷ과 ㅁ, ㅐ와 ㅓ의 모양이 닮음)를 쓴 예다. 같은 방식으로 대한민국→머한민국, 대구→머구, 대박→머박이 나왔다. 실존 대통령 이름까지 비튼 표기도 돌았으나 사전에는 일반 명사형만 싣는다.', '{"de": "Nutzt den Yaminjeongeum-Tausch 대→머 (ㄷ/ㅁ und ㅐ/ㅓ ähneln sich), wie bei 머한민국, 머구 und 머박. Es kursierten auch Formen mit Namen echter Präsidenten, hier steht nur die allgemeine Form.", "en": "Uses the yaminjeongeum 대→머 swap (ㄷ/ㅁ and ㅐ/ㅓ look alike), the same one behind 머한민국, 머구 and 머박. Versions twisting actual presidents names also circulated, but only the common-noun form is listed here.", "es": "Usa el cambio 대→머 del yaminjeongeum (ㄷ/ㅁ y ㅐ/ㅓ se parecen), el mismo de 머한민국, 머구 y 머박. También circularon versiones con nombres de presidentes reales, pero aquí solo figura la forma común.", "ja": "ヤミン正音の「대→머」の置き換え(ㄷとㅁ、ㅐとㅓが似る)の例。同じ方法で머한민국、머구、머박が生まれた。実在の大統領名まで崩した表記も出回ったが、辞典には一般名詞形だけを載せる。", "vi": "Dùng kiểu đổi 대→머 của yaminjeongeum (ㄷ/ㅁ và ㅐ/ㅓ trông giống), giống như 머한민국, 머구, 머박. Cũng có cách viết bóp méo tên tổng thống thật, nhưng từ điển chỉ ghi dạng danh từ chung."}'::jsonb, '정치 이야기에 섞으면 비꼬는 뉘앙스로 읽힐 수 있다. 가볍게 쓰는 말이니 공식적인 글에는 쓰지 않는다.', '{"de": "In politischen Gesprächen kann es spöttisch wirken. Ein lockeres Wort, nicht für formelle Texte.", "en": "Dropped into political talk it can read as mocking. It is a light word; keep it out of formal writing.", "es": "En conversaciones políticas puede sonar burlón. Es una palabra ligera; no la uses en textos formales.", "ja": "政治の話に混ぜると皮肉っぽく読まれることがある。軽い言葉なので公式な文章には使わない。", "vi": "Chen vào chuyện chính trị có thể bị hiểu là mỉa mai. Đây là từ vui, không dùng trong văn bản trang trọng."}'::jsonb, array['머한민국', '머박', '세종머앟']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "President (look-alike spelling)"}, {"lang": "🇯🇵 JA", "text": "大統領(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "总统(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Tổng thống (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Presidente (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Präsident (Ähnlichkeitsschreibung)"}]'::jsonb),
('570', '머한민국', 'Meo-han-min-guk', 'outdated-slang', 'yaminjeongeum', '‘대한민국’을 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 대한민국 (Republik Korea) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 대한민국 (Republic of Korea)", "es": "Reescritura de 대한민국 (Corea del Sur) con hangul parecido", "ja": "「大韓民国」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 대한민국 (Hàn Quốc) bằng chữ Hàn trông giống"}'::jsonb, '[머한민국]', '[{"type": "명사", "examples": [{"de": "Lieferung in dreißig Minuten? Typisch Meo-han-min-guk.", "es": "¿Reparto en treinta minutos? Así es meo-han-min-guk.", "ja": "30分で配達来るの見ると、さすが머한민국だわ。", "vi": "Giao đồ ba mươi phút là tới, đúng là meo-han-min-guk.", "eng": "Delivery in thirty minutes? That is meo-han-min-guk for you.", "kor": "배달 30분 만에 오는 거 보면 역시 머한민국이다."}], "definition": "‘대한민국’의 ‘대’를 모양이 닮은 ‘머’로 바꿔 쓴 야민정음 표기. 한국을 장난스럽게, 때로는 한국 사회를 자조하며 부를 때 쓴다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 대한민국 mit 머 statt 대. Ein scherzhafter Name für Korea, manchmal mit selbstironischem Blick auf die koreanische Gesellschaft.", "en": "A yaminjeongeum spelling of 대한민국 with 대 swapped for the look-alike 머. A playful name for Korea, sometimes used with a self-mocking edge about Korean society.", "es": "Grafía yaminjeongeum de 대한민국, cambiando 대 por el parecido 머. Nombre en broma para Corea, a veces con autoironía sobre la sociedad coreana.", "ja": "「대한민국」の「대」を形の似た「머」に替えたヤミン正音表記。韓国をおどけて、時には韓国社会を自嘲して呼ぶときに使う。", "vi": "Cách viết yaminjeongeum của 대한민국, đổi 대 thành 머. Cách gọi đùa Hàn Quốc, đôi khi mang ý tự giễu xã hội Hàn."}}]'::jsonb, '야민정음의 ‘대→머’ 바꾸기를 쓴 예로, 머통령·머구·머박과 같은 방식이다.', '{"de": "Ein Beispiel für den Yaminjeongeum-Tausch 대→머, wie bei 머통령, 머구 und 머박.", "en": "An example of the yaminjeongeum 대→머 swap, the same pattern as 머통령, 머구 and 머박.", "es": "Ejemplo del cambio 대→머 del yaminjeongeum, igual que 머통령, 머구 y 머박.", "ja": "ヤミン正音の「대→머」の置き換えの例で、머통령・머구・머박と同じ方法。", "vi": "Ví dụ của kiểu đổi 대→머 trong yaminjeongeum, giống 머통령, 머구, 머박."}'::jsonb, '‘역시 머한민국’처럼 한국다운 일을 보고 감탄하거나 투덜댈 때 쓴다. 글로만 쓰는 장난 표기다.', '{"de": "Etwa 역시 머한민국 (typisch Korea), um über typisch Koreanisches zu staunen oder zu meckern. Nur schriftlich.", "en": "Used as in 역시 머한민국 (so very Korea) to marvel or grumble at something typically Korean. A written-only joke spelling.", "es": "Se usa como 역시 머한민국 (qué coreano) para maravillarse o quejarse de algo muy de Corea. Grafía de broma solo escrita.", "ja": "「さすが머한민국」のように、韓国らしい出来事に感心したりぼやいたりするときに使う。文字でだけ使う遊び表記。", "vi": "Dùng kiểu 역시 머한민국 (đúng chất Hàn) để khen hay càu nhàu chuyện rất Hàn Quốc. Chỉ dùng khi viết."}'::jsonb, array['머통령', '머구광역시', '세종머앟']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Korea (look-alike spelling of 대한민국)"}, {"lang": "🇯🇵 JA", "text": "大韓民国(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "大韩民国(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Hàn Quốc (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Corea (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Korea (Ähnlichkeitsschreibung)"}]'::jsonb),
('571', '머구광역시', 'Meo-gu-gwang-yeok-si', 'outdated-slang', 'yaminjeongeum', '‘대구광역시’를 글자 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 대구광역시 (Stadt Daegu) mit ähnlich aussehenden Hangul", "en": "A look-alike-Hangul respelling of 대구광역시 (Daegu Metropolitan City)", "es": "Reescritura de 대구광역시 (la ciudad de Daegu) con hangul parecido", "ja": "「大邱広域市」を形の似たハングルに置き換えた表記", "vi": "Cách viết lại 대구광역시 (thành phố Daegu) bằng chữ Hàn trông giống"}'::jsonb, '[머구광역씨]', '[{"type": "명사", "examples": [{"de": "Diesen Sommer war Meo-gu echt heiß.", "es": "Este verano meo-gu ha sido un horno.", "ja": "今年の夏、머구マジで暑かった。", "vi": "Hè này meo-gu nóng kinh khủng.", "eng": "Meo-gu was seriously hot this summer.", "kor": "이번 여름 머구 진짜 덥더라."}], "definition": "‘대구광역시’의 ‘대’를 ‘머’로 바꿔 쓴 야민정음 표기. 줄여서 ‘머구’라고도 한다. ‘광’을 ‘팡’으로 바꾼 ‘머구팡역시’처럼 더 비튼 변형도 있다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 대구광역시 mit 머 statt 대, oft zu 머구 verkürzt. Es gibt noch verdrehtere Formen wie 머구팡역시, bei der 광 zu 팡 wird.", "en": "A yaminjeongeum spelling of 대구광역시 with 대 turned into 머; often shortened to 머구. Further-twisted versions exist, such as 머구팡역시 with 광 changed to 팡.", "es": "Grafía yaminjeongeum de 대구광역시 con 대 convertido en 머; a menudo se acorta a 머구. Hay versiones aún más retorcidas, como 머구팡역시, con 광 cambiado a 팡.", "ja": "「대구광역시」の「대」を「머」に替えたヤミン正音表記。略して「머구」とも言う。「광」を「팡」にした「머구팡역시」のようにさらに崩した形もある。", "vi": "Cách viết yaminjeongeum của 대구광역시, đổi 대 thành 머; thường rút gọn là 머구. Còn có biến thể méo hơn như 머구팡역시, đổi 광 thành 팡."}}]'::jsonb, '야민정음의 ‘대→머’ 바꾸기를 지명에 쓴 예다. 대구가 여름에 매우 더운 도시라 ‘대프리카’와 함께 인터넷에서 자주 입에 오르던 지명이다.', '{"de": "Der Yaminjeongeum-Tausch 대→머 auf einen Ortsnamen angewandt. Daegu, berüchtigt für heiße Sommer, war schon mit dem Spitznamen 대프리카 (Daegu + Afrika) ein Internetliebling.", "en": "The yaminjeongeum 대→머 swap applied to a place name. Daegu, famously hot in summer, was already an internet favourite alongside the nickname 대프리카 (Daegu + Africa).", "es": "El cambio 대→머 del yaminjeongeum aplicado a un topónimo. Daegu, famosa por su calor veraniego, ya era habitual en internet junto al apodo 대프리카 (Daegu + África).", "ja": "ヤミン正音の「대→머」を地名に使った例。夏がとても暑い大邱は「대프리카」とともにネットでよく話題になる地名だった。", "vi": "Kiểu đổi 대→머 áp dụng cho địa danh. Daegu nổi tiếng nóng mùa hè, vốn đã hay được nhắc trên mạng cùng biệt danh 대프리카 (Daegu + châu Phi)."}'::jsonb, '실제로는 줄임형 ‘머구’를 훨씬 많이 쓴다. 지역을 비하하는 말은 아니지만 그 지역 사람 앞에서는 가볍게만 쓰는 편이 낫다.', '{"de": "In der Praxis ist die Kurzform 머구 weit häufiger. Kein Schimpfwort, aber bei Leuten aus Daegu lieber locker einsetzen.", "en": "The short form 머구 is far more common in practice. It is not a slur, but keep it light around people from Daegu.", "es": "En la práctica se usa mucho más la forma corta 머구. No es despectivo, pero con gente de Daegu mejor usarlo con ligereza.", "ja": "実際には略形「머구」のほうがずっと多く使われる。地域を見下す言葉ではないが、その地域の人の前では軽く使う程度がよい。", "vi": "Thực tế dạng rút gọn 머구 phổ biến hơn nhiều. Không phải từ miệt thị, nhưng trước người Daegu nên dùng nhẹ nhàng."}'::jsonb, array['머한민국', '머통령', '머박']::text[], array['머구', '머구팡역시']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Daegu (look-alike spelling)"}, {"lang": "🇯🇵 JA", "text": "大邱(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "大邱(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Daegu (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Daegu (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Daegu (Ähnlichkeitsschreibung)"}]'::jsonb),
('572', '머튽', 'Meo-tyung', 'outdated-slang', 'yaminjeongeum', '‘대장’을 한자와 한글 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Umschreibung von 대장 (Boss) mit Hangul- und Hanja-Formen", "en": "A look-alike respelling of 대장 (boss / captain) mixing Hangul and hanja shapes", "es": "Reescritura de 대장 (jefe) mezclando formas de hangul y hanja", "ja": "「대장(大将)」をハングルと漢字の形で崩した表記", "vi": "Cách viết lại 대장 (thủ lĩnh) pha hình chữ Hàn và chữ Hán"}'::jsonb, '[머튱]', '[{"type": "명사", "examples": [{"de": "Beim Zocken ist unser Meo-tyung der Beste.", "es": "En videojuegos, nuestro meo-tyung es el mejor.", "ja": "ゲームならやっぱりうちの머튽が最強。", "vi": "Chơi game thì meo-tyung nhà mình là nhất.", "eng": "When it comes to games, our meo-tyung is the best.", "kor": "게임은 역시 우리 머튽이 최고지."}], "definition": "‘대장’의 ‘대’를 ‘머’로, ‘장’을 한자 ‘長’의 생김새를 본뜬 ‘튽’으로 바꿔 쓴 야민정음 표기. 무리의 우두머리나 어떤 분야에서 제일 잘하는 사람을 장난스럽게 부를 때 쓴다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung von 대장: 대 wird 머, 장 wird 튽, das die Form des Hanja 長 nachahmt. Ein scherzhafter Titel für den Anführer einer Gruppe oder den Besten in etwas.", "en": "A yaminjeongeum spelling of 대장: 대 becomes 머, and 장 becomes 튽, which mimics the shape of the hanja 長. A playful title for the leader of a group or the best at something.", "es": "Grafía yaminjeongeum de 대장: 대 pasa a 머, y 장 a 튽, que imita la forma del hanja 長. Título en broma para el líder de un grupo o el mejor en algo.", "ja": "「대장」の「대」を「머」に、「장」を漢字「長」の形をまねた「튽」に替えたヤミン正音表記。仲間のボスや、ある分野でいちばんうまい人をおどけて呼ぶときに使う。", "vi": "Cách viết yaminjeongeum của 대장: 대 thành 머, 장 thành 튽 bắt chước hình chữ Hán 長. Cách gọi đùa thủ lĩnh nhóm hay người giỏi nhất một lĩnh vực."}}]'::jsonb, '한글끼리만이 아니라 한자 모양까지 끌어온 야민정음이다. ‘長’이 한글 ‘튽’처럼 보인다는 데서 ‘장→튽’ 바꾸기가 나왔고, 사람 이름의 ‘장’을 바꾼 표기로도 널리 퍼졌다.', '{"de": "Yaminjeongeum, das auch Hanja-Formen nutzt, nicht nur Hangul. Der Tausch 장→튽 kommt daher, dass 長 wie der Hangul-Block 튽 aussieht, und verbreitete sich auch in Namen mit 장.", "en": "Yaminjeongeum that borrows from hanja shapes, not just Hangul. The 장→튽 swap comes from 長 looking like the Hangul block 튽, and it spread widely in respellings of peoples names containing 장 as well.", "es": "Yaminjeongeum que toma formas de los hanja, no solo del hangul. El cambio 장→튽 viene de que 長 parece el bloque hangul 튽, y se extendió también en nombres de personas con 장.", "ja": "ハングル同士だけでなく漢字の形まで借りたヤミン正音。「長」がハングルの「튽」に見えることから「장→튽」の置き換えが生まれ、人名の「장」を替えた表記としても広まった。", "vi": "Yaminjeongeum mượn cả hình chữ Hán chứ không chỉ Hangul. Kiểu đổi 장→튽 đến từ việc 長 trông giống khối chữ Hangul 튽, và cũng lan rộng khi viết lại tên người có chữ 장."}'::jsonb, '친한 사이에서 우두머리를 추켜세울 때 쓴다. 읽는 법이 정해져 있지 않아 글로만 쓰는 말이다.', '{"de": "Unter Freunden, um den Anführer hochleben zu lassen. Ohne feste Aussprache, daher nur schriftlich.", "en": "Used among friends to hype up the ringleader. It has no settled pronunciation, so it lives in writing only.", "es": "Se usa entre amigos para ensalzar al cabecilla. No tiene pronunciación fija, así que es solo escrito.", "ja": "親しい間でリーダーを持ち上げるときに使う。読み方が決まっていないので文字だけで使う言葉。", "vi": "Dùng giữa bạn bè để tâng bốc người cầm đầu. Không có cách đọc cố định nên chỉ dùng khi viết."}'::jsonb, array['머박', '머통령', '티本']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Boss / captain (look-alike spelling)"}, {"lang": "🇯🇵 JA", "text": "大将(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "老大(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Thủ lĩnh (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Jefe (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Boss (Ähnlichkeitsschreibung)"}]'::jsonb),
('573', '푸라면', 'Pu-ra-myeon', 'outdated-slang', 'yaminjeongeum', '‘신라면’을 한자 ‘辛’ 모양대로 바꿔 쓴 야민정음 표기', '{"de": "Shin Ramyun, umgeschrieben nach der Form seines Hanja 辛", "en": "Shin Ramyun respelled from the shape of its hanja 辛", "es": "Shin Ramyun reescrito según la forma de su hanja 辛", "ja": "「辛ラーメン」を漢字「辛」の形で崩した表記", "vi": "Shin Ramyun viết lại theo hình chữ Hán 辛"}'::jsonb, '[푸라면]', '[{"type": "명사", "examples": [{"de": "Als Mitternachtssnack natürlich Pu-ra-myeon.", "es": "Para picar de noche, pu-ra-myeon, claro.", "ja": "夜食はやっぱり푸라면でしょ。", "vi": "Ăn khuya thì phải là pu-ra-myeon.", "eng": "For a late-night snack, it has to be pu-ra-myeon.", "kor": "야식은 역시 푸라면이지."}], "definition": "라면 ‘신라면’을 가리키는 야민정음 표기. 봉지에 크게 쓰인 한자 ‘辛(매울 신)’이 한글 ‘푸’처럼 보인다는 데서 나왔다.", "definition_i18n": {"de": "Ein Yaminjeongeum-Name für Shin-Ramyun-Instantnudeln. Das große Hanja 辛 (scharf) auf der Packung sieht aus wie das Hangul 푸, daher 푸라면.", "en": "A yaminjeongeum name for Shin Ramyun instant noodles. The big hanja 辛 (spicy) printed on the packet looks like the Hangul 푸, hence 푸라면.", "es": "Nombre yaminjeongeum de los fideos Shin Ramyun. El gran hanja 辛 (picante) impreso en el paquete parece el hangul 푸, de ahí 푸라면.", "ja": "ラーメン「辛ラーメン」を指すヤミン正音表記。袋に大きく書かれた漢字「辛」がハングルの「푸」に見えることから生まれた。", "vi": "Tên yaminjeongeum của mì Shin Ramyun. Chữ Hán 辛 (cay) in to trên gói trông như chữ Hangul 푸, nên mới thành 푸라면."}}]'::jsonb, '한자 생김새를 한글로 읽어 내는 야민정음의 대표 예다. 신라면 봉지의 큼직한 ‘辛’ 글자가 누구에게나 익숙해서 설명 없이도 통했다.', '{"de": "Ein klassisches Beispiel für Yaminjeongeum, das Hanja-Formen als Hangul liest. Das riesige 辛 auf der Shin-Ramyun-Packung war so bekannt, dass der Witz keine Erklärung brauchte.", "en": "A classic example of yaminjeongeum reading hanja shapes as Hangul. The oversized 辛 on the Shin Ramyun packet was so familiar that the joke needed no explanation.", "es": "Ejemplo clásico de yaminjeongeum que lee formas de hanja como hangul. El enorme 辛 del paquete de Shin Ramyun era tan conocido que el chiste no necesitaba explicación.", "ja": "漢字の形をハングルとして読むヤミン正音の代表例。辛ラーメンの袋の大きな「辛」の字が誰にでもなじみ深く、説明なしで通じた。", "vi": "Ví dụ tiêu biểu của yaminjeongeum đọc hình chữ Hán thành Hangul. Chữ 辛 to trên gói Shin Ramyun quá quen thuộc nên không cần giải thích."}'::jsonb, '특정 상품 이름을 비튼 말이라 그 라면을 가리킬 때만 쓴다. 매운 라면 전반을 뜻하지는 않는다.', '{"de": "Verdreht einen bestimmten Produktnamen und meint nur diese Nudeln, nicht scharfe Nudeln allgemein.", "en": "It twists a specific product name, so it only means that ramyeon, not spicy noodles in general.", "es": "Deforma un nombre de producto concreto, así que solo designa esos fideos, no los picantes en general.", "ja": "特定の商品名を崩した言葉なので、そのラーメンを指すときだけ使う。辛いラーメン全般の意味ではない。", "vi": "Là tên sản phẩm cụ thể bị biến tấu, nên chỉ dùng cho loại mì đó, không phải mì cay nói chung."}'::jsonb, array['괄도네넴띤', 'RtA', '티本']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Shin Ramyun (look-alike spelling)"}, {"lang": "🇯🇵 JA", "text": "辛ラーメン(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "辛拉面(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Mì Shin Ramyun (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Shin Ramyun (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Shin Ramyun (Ähnlichkeitsschreibung)"}]'::jsonb),
('574', '티本', 'Ti-bon', 'outdated-slang', 'yaminjeongeum', '‘日本(일본)’의 ‘日’을 한글 ‘티’로 읽은 야민정음 표기', '{"de": "日本 (Japan), wobei 日 als Hangul 티 gelesen wird", "en": "日本 (Japan) with 日 read as the Hangul 티", "es": "日本 (Japón) con 日 leído como el hangul 티", "ja": "「日本」の「日」をハングル「티」と読んだ表記", "vi": "日本 (Nhật Bản) với 日 đọc thành chữ Hangul 티"}'::jsonb, '[티본]', '[{"type": "명사", "examples": [{"de": "Diesen Urlaub geht es nach Ti-bon.", "es": "Estas vacaciones vamos a ti-bon.", "ja": "今回の休暇は티本に行くことにした。", "vi": "Kỳ nghỉ này tụi mình quyết đi ti-bon.", "eng": "We decided to go to ti-bon for this vacation.", "kor": "이번 휴가는 티本 가기로 했어."}], "definition": "‘일본’을 한자로 쓴 ‘日本’에서 ‘日’이 한글 ‘티’처럼 보인다는 점을 이용한 야민정음 표기. 일본을 장난스럽게 가리킨다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung, die darauf beruht, dass 日 in 日本 (Japan) wie das Hangul 티 aussieht. Eine scherzhafte Bezeichnung für Japan.", "en": "A yaminjeongeum spelling built on the fact that 日 in 日本 (Japan) looks like the Hangul 티. A joking way to refer to Japan.", "es": "Grafía yaminjeongeum basada en que el 日 de 日本 (Japón) parece el hangul 티. Forma de broma de referirse a Japón.", "ja": "「日本」の「日」がハングルの「티」に見えることを利用したヤミン正音表記。日本をおどけて指す。", "vi": "Cách viết yaminjeongeum dựa trên việc chữ 日 trong 日本 (Nhật Bản) trông như chữ Hangul 티. Cách gọi đùa Nhật Bản."}}]'::jsonb, '한자의 생김새를 한글로 읽는 야민정음 방식이다. ‘本’은 그대로 두고 ‘日’만 한글로 바꿔, 한자와 한글이 섞인 채로 쓴다는 점이 특이하다.', '{"de": "Die Yaminjeongeum-Methode, Hanja-Formen als Hangul zu lesen. Nur 日 wird umgewandelt, 本 bleibt, sodass Hanja und Hangul ungewöhnlich gemischt sind.", "en": "The yaminjeongeum method of reading hanja shapes as Hangul. Only 日 is converted while 本 stays as it is, so the word is unusual in mixing hanja and Hangul.", "es": "El método yaminjeongeum de leer formas de hanja como hangul. Solo cambia 日 y 本 se queda igual, así que mezcla hanja y hangul, algo poco común.", "ja": "漢字の形をハングルとして読むヤミン正音の方法。「本」はそのままで「日」だけをハングルに替え、漢字とハングルが混ざったまま書く点が特徴的。", "vi": "Cách yaminjeongeum đọc hình chữ Hán thành Hangul. Chỉ đổi 日, giữ nguyên 本, nên từ này đặc biệt ở chỗ trộn chữ Hán và Hangul."}'::jsonb, '한자를 섞어 써야 해서 입력이 번거로워 자주 쓰이지는 않는다. 나라 이름을 비튼 말이라 맥락에 따라 조롱으로 읽힐 수 있으니 조심해서 쓴다.', '{"de": "Man muss Hanja eintippen, daher wurde es nie sehr verbreitet. Als verdrehter Ländername kann es je nach Kontext spöttisch wirken, also mit Bedacht verwenden.", "en": "Typing it requires hanja, so it never became very common. As a twisted country name it can read as mockery in some contexts, so use it with care.", "es": "Hay que teclear hanja, así que nunca fue muy común. Al deformar el nombre de un país puede sonar a burla según el contexto; úsalo con cuidado.", "ja": "漢字を混ぜる必要があり入力が面倒なので、あまり使われない。国名を崩した言葉なので文脈によっては嘲笑と受け取られることもあり、注意して使う。", "vi": "Phải gõ chữ Hán nên không phổ biến. Vì biến tấu tên một quốc gia, tùy ngữ cảnh có thể bị hiểu là chế giễu, nên dùng cẩn thận."}'::jsonb, array['푸라면', '머튽', '머한민국']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Japan (look-alike spelling of 日本)"}, {"lang": "🇯🇵 JA", "text": "日本(ヤミン正音表記)"}, {"lang": "🇨🇳 ZH", "text": "日本(形近写法)"}, {"lang": "🇻🇳 VI", "text": "Nhật Bản (cách viết giống)"}, {"lang": "🇪🇸 ES", "text": "Japón (grafía parecida)"}, {"lang": "🇩🇪 DE", "text": "Japan (Ähnlichkeitsschreibung)"}]'::jsonb),
('575', 'ldH', 'Bae (ldH)', 'outdated-slang', 'yaminjeongeum', '‘배’를 옆으로 돌려 알파벳처럼 적은 야민정음 표기', '{"de": "Das Hangul 배, seitlich gedreht, sodass es wie die Buchstaben ldH aussieht", "en": "The Hangul 배 turned sideways so it looks like the letters ldH", "es": "El hangul 배 girado de lado para que parezca las letras ldH", "ja": "「배」を横に倒してアルファベットのように書いた表記", "vi": "Chữ Hangul 배 xoay ngang trông như chữ cái ldH"}'::jsonb, '[배]', '[{"type": "명사", "examples": [{"de": "Mein ldH knurrt so, ich kann nichts machen.", "es": "Tengo tanta hambre (ldH vacía) que no puedo hacer nada.", "ja": "ldH減りすぎて何もできない。", "vi": "Đói ldH quá chẳng làm được gì.", "eng": "I am so hungry (my ldH is empty) I cannot do anything.", "kor": "ldH 고파서 아무것도 못 하겠어."}], "definition": "한글 ‘배’를 옆으로 90도 돌려 보면 알파벳 ‘ldH’처럼 보인다는 데서 나온 야민정음 표기. 먹는 배, 타는 배, 몸의 배 어느 쪽이든 ‘배’ 자리에 쓴다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung, weil 배 um 90 Grad gedreht wie die lateinischen Buchstaben ldH aussieht. Steht für jedes 배: Birne, Boot oder Bauch.", "en": "A yaminjeongeum spelling from the fact that 배, turned 90 degrees, looks like the Latin letters ldH. It stands in for any 배: the pear, the boat or the belly.", "es": "Grafía yaminjeongeum que nace de que 배, girado 90 grados, parece las letras latinas ldH. Sustituye a cualquier 배: la pera, el barco o la barriga.", "ja": "ハングルの「배」を横に90度回すとアルファベットの「ldH」に見えることから生まれたヤミン正音表記。梨・船・お腹、どの「배」の代わりにも使う。", "vi": "Cách viết yaminjeongeum xuất phát từ việc chữ 배 xoay 90 độ trông như chữ cái ldH. Dùng thay cho mọi nghĩa của 배: quả lê, con thuyền hay cái bụng."}}]'::jsonb, '글자를 돌려서 다른 문자로 보이게 하는 회전형 야민정음이다. 한글을 로마자로 바꿔 읽는다는 점에서 너구리→RtA와 같은 계열이다.', '{"de": "Rotations-Yaminjeongeum: Dreht man ein Zeichen, sieht es wie eine andere Schrift aus. Hangul als lateinische Buchstaben zu lesen, gehört zur Familie von 너구리→RtA.", "en": "Rotation-type yaminjeongeum, where turning a character makes it look like a different script. Reading Hangul as Latin letters puts it in the same family as 너구리→RtA.", "es": "Yaminjeongeum de rotación: al girar un carácter parece de otra escritura. Leer hangul como letras latinas lo sitúa en la misma familia que 너구리→RtA.", "ja": "文字を回して別の文字に見せる回転型のヤミン正音。ハングルをローマ字として読む点で너구리→RtAと同じ系列。", "vi": "Yaminjeongeum kiểu xoay: xoay chữ để trông như hệ chữ khác. Đọc Hangul thành chữ Latin nên cùng họ với 너구리→RtA."}'::jsonb, '글로만 쓰는 장난 표기이고, 읽을 때는 그냥 ‘배’라고 읽는다. 처음 보는 사람은 알아보기 어려우니 설명을 곁들이는 편이 좋다.', '{"de": "Eine rein schriftliche Scherzschreibung, gelesen einfach als 배. Wer es zum ersten Mal sieht, versteht es oft nicht, eine Erklärung hilft.", "en": "A written-only joke spelling, read simply as 배. People seeing it for the first time may not get it, so an explanation helps.", "es": "Grafía de broma solo escrita; se lee simplemente 배. Quien la ve por primera vez puede no entenderla, así que conviene explicarla.", "ja": "文字だけの遊び表記で、読むときはただ「배」と読む。初めて見る人にはわかりにくいので説明を添えるとよい。", "vi": "Chỉ là cách viết đùa, đọc đơn giản là 배. Người lần đầu thấy khó hiểu, nên kèm lời giải thích thì tốt hơn."}'::jsonb, array['RtA', '롬곡', '댕댕이']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pear / boat / belly (배 turned sideways)"}, {"lang": "🇯🇵 JA", "text": "梨・船・お腹(「배」を横倒し)"}, {"lang": "🇨🇳 ZH", "text": "梨/船/肚子(「배」横着写)"}, {"lang": "🇻🇳 VI", "text": "Lê / thuyền / bụng (배 xoay ngang)"}, {"lang": "🇪🇸 ES", "text": "Pera / barco / barriga (배 de lado)"}, {"lang": "🇩🇪 DE", "text": "Birne / Boot / Bauch (배 seitlich)"}]'::jsonb),
('576', 'RtA', 'Neo-gu-ri (RtA)', 'outdated-slang', 'yaminjeongeum', '‘너구리’를 옆으로 돌려 알파벳처럼 적은 야민정음 표기', '{"de": "Das Hangul 너구리, seitlich gedreht, sodass es wie RtA aussieht", "en": "The Hangul 너구리 turned sideways so it looks like RtA", "es": "El hangul 너구리 girado de lado para que parezca RtA", "ja": "「너구리」を横に倒してアルファベットのように書いた表記", "vi": "Chữ 너구리 xoay ngang trông như RtA"}'::jsonb, '[너구리]', '[{"type": "명사", "examples": [{"de": "An Regentagen muss eine Schüssel RtA her.", "es": "Un día de lluvia pide un bol de RtA.", "ja": "雨の日はRtAを一杯でしょ。", "vi": "Trời mưa là phải có bát RtA.", "eng": "A rainy day calls for a bowl of RtA.", "kor": "비 오는 날엔 RtA 한 그릇이지."}], "definition": "‘너구리’ 세 글자를 옆으로 90도 돌려 보면 알파벳 ‘RtA’처럼 보인다는 데서 나온 야민정음 표기. 동물 너구리보다 같은 이름의 라면을 가리킬 때 더 많이 쓰였다.", "definition_i18n": {"de": "Eine Yaminjeongeum-Schreibung, weil die drei Silben von 너구리 um 90 Grad gedreht wie RtA aussehen. Meist für die gleichnamige Ramyeon-Marke statt für den Marderhund benutzt.", "en": "A yaminjeongeum spelling from the fact that the three syllables of 너구리, turned 90 degrees, look like the letters RtA. It was used more for the ramyeon brand of that name than for the raccoon dog itself.", "es": "Grafía yaminjeongeum que nace de que las tres sílabas de 너구리, giradas 90 grados, parecen las letras RtA. Se usó más para la marca de fideos de ese nombre que para el mapache japonés.", "ja": "「너구리」の3文字を横に90度回すとアルファベットの「RtA」に見えることから生まれたヤミン正音表記。動物のタヌキより、同名のラーメンを指すことが多かった。", "vi": "Cách viết yaminjeongeum vì ba âm tiết 너구리 xoay 90 độ trông như chữ RtA. Hay dùng để chỉ loại mì cùng tên hơn là con lửng chó."}}]'::jsonb, '한글을 돌려 로마자로 읽는 회전형 야민정음의 대표 예다. 배→ldH와 같은 방식이며, 라면 포장의 로고와 겹쳐 더 널리 알려졌다.', '{"de": "Paradebeispiel für Rotations-Yaminjeongeum, das gedrehtes Hangul als lateinische Buchstaben liest, derselbe Trick wie 배→ldH. Die Verbindung zur Nudelverpackung machte es besonders bekannt.", "en": "A flagship example of rotation-type yaminjeongeum that reads turned Hangul as Latin letters, the same trick as 배→ldH. Its link to the ramyeon packaging made it especially well known.", "es": "Ejemplo estrella del yaminjeongeum de rotación que lee hangul girado como letras latinas, el mismo truco que 배→ldH. Su vínculo con el paquete de fideos lo hizo muy conocido.", "ja": "ハングルを回してローマ字として読む回転型ヤミン正音の代表例。배→ldHと同じ方法で、ラーメンのパッケージと結びついてより広く知られた。", "vi": "Ví dụ tiêu biểu của yaminjeongeum kiểu xoay đọc Hangul thành chữ Latin, cùng mẹo với 배→ldH. Gắn với bao bì mì nên càng nổi tiếng."}'::jsonb, '글로만 쓰고 읽을 때는 ‘너구리’라고 읽는다. 라면 이야기에서 가장 잘 통한다.', '{"de": "Nur schriftlich, gelesen als 너구리. Am besten beim Thema Nudeln.", "en": "Written only, and read aloud as 너구리. It lands best in ramyeon talk.", "es": "Solo escrito; se lee 너구리. Funciona mejor hablando de fideos.", "ja": "文字だけで使い、読むときは「너구리」と読む。ラーメンの話でいちばん通じる。", "vi": "Chỉ dùng khi viết, đọc là 너구리. Hợp nhất khi nói chuyện về mì."}'::jsonb, array['ldH', '푸라면', '괄도네넴띤']::text[], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Neoguri (raccoon dog / the ramyeon) turned sideways"}, {"lang": "🇯🇵 JA", "text": "ノグリ(タヌキ/ラーメン)の横倒し表記"}, {"lang": "🇨🇳 ZH", "text": "浣熊(拉面名)横着写"}, {"lang": "🇻🇳 VI", "text": "Neoguri (lửng chó / mì) xoay ngang"}, {"lang": "🇪🇸 ES", "text": "Neoguri (mapache / los fideos) de lado"}, {"lang": "🇩🇪 DE", "text": "Neoguri (Marderhund / Nudeln) seitlich"}]'::jsonb);
